import { path } from '@servicenow/sdk-build-core'
import { createTestContext, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

describe('copy-resolution-notes-subflow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Round-Trip Test: copy-resolution-notes-subflow
     *
     * XML Source: sys_hub_flow_c186e939f1d242adb1c85c885da8ce5d.xml
     * Fluent Source: subflow-definition-examples.now.ts (Copy resolution notes)
     *
     * Subflow Name: Copy resolution notes
     * Description: Subflow with FlowObject inputs, flow variables, and flowPriority
     *
     * This test validates:
     * - XML → Fluent transformation generates correct TypeScript code
     * - Fluent → XML transformation preserves all subflow data
     * - Round-trip maintains data integrity
     *
     * Subflow Structure:
     * - Type: Subflow
     * - flowPriority: LOW
     * - Inputs: similarCase (StringColumn), currentCase (FlowObject with nested fields)
     * - Outputs: status (StringColumn)
     * - Flow Variables: resolutionNotes (StringColumn)
     * - Flow Logic: assignSubflowOutputs with status: 'Success'
     *
     * Features: FlowObject inputs with nested fields, flow variables, flowPriority, assignSubflowOutputs
     */
    test('copy-resolution-notes-subflow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_c186e939f1d242adb1c85c885da8ce5d.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Validate imports
        expect(fluentContent).toContain('import {')
        expect(fluentContent).toContain('Subflow')
        expect(fluentContent).toContain('wfa')

        // Validate subflow definition
        expect(fluentContent).toContain('Subflow(')
        expect(fluentContent).toContain("name: 'Copy resolution notes'")
        expect(fluentContent).toContain("flowPriority: 'LOW'")

        // Validate inputs - similarCase (StringColumn)
        expect(fluentContent).toContain('inputs:')
        expect(fluentContent).toContain('similarCase: StringColumn(')
        expect(fluentContent).toContain("label: 'Similar case'")

        // Validate inputs - currentCase (FlowObject with nested fields)
        expect(fluentContent).toContain('currentCase: FlowObject(')
        expect(fluentContent).toContain('fields:')
        // Validate nested field: resolutionNotes
        expect(fluentContent).toContain('resolutionNotes: StringColumn(')
        expect(fluentContent).toContain("label: 'Resolution notes'")
        // Validate nested field: caseId
        expect(fluentContent).toContain('caseId: StringColumn(')
        expect(fluentContent).toContain("label: 'Case ID'")
        // Validate FlowObject label
        expect(fluentContent).toContain("label: 'currentCase'")

        // Validate outputs
        expect(fluentContent).toContain('outputs:')
        expect(fluentContent).toContain('status: StringColumn(')
        expect(fluentContent).toContain("label: 'Status'")
        expect(fluentContent).toContain('mandatory: true')

        // Validate flow variables
        expect(fluentContent).toContain('flowVariables:')
        expect(fluentContent).toContain('resolutionNotes: StringColumn(')
        expect(fluentContent).toContain("label: 'Resolution notes'")

        // Validate Flow Logic: assignSubflowOutputs
        expect(fluentContent).toContain('wfa.flowLogic.assignSubflowOutputs(')
        expect(fluentContent).toContain("annotation: 'Test Subflow Outputs 2'")
        expect(fluentContent).toContain('_params.outputs')
        expect(fluentContent).toContain("status: 'Success'")

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)!.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        expect(mergedRecords['sys_hub_flow']).toBeDefined()

        // Validate subflow record
        const flows = mergedRecords['sys_hub_flow']
        const subflow = flows.find((f: any) => f.name === 'Copy resolution notes')
        expect(subflow).toBeDefined()
        expect(subflow.type).toBe('subflow')
        expect(subflow.generation_source).toBe('fluent')
        expect(subflow.run_as).toBe('system')
        expect(subflow.flow_priority).toBe('LOW')

        // Validate subflow inputs
        if (mergedRecords['sys_hub_flow_input']) {
            const inputs = mergedRecords['sys_hub_flow_input'].filter((i: any) => i.model === subflow.sys_id)
            expect(inputs.length).toBe(2) // Exact count: similarCase and currentCase

            // Validate similarCase input
            const similarCaseInput = inputs.find((i: any) => i.element === 'similarCase')
            expect(similarCaseInput).toBeDefined()
            expect(similarCaseInput.label).toBe('Similar case')
            expect(similarCaseInput.internal_type).toBe('string')

            // Validate currentCase input (FlowObject - stored as string with attributes)
            const currentCaseInput = inputs.find((i: any) => i.element === 'currentCase')
            expect(currentCaseInput).toBeDefined()
            expect(currentCaseInput.label).toBe('currentCase')
            expect(currentCaseInput.internal_type).toBe('string')
            expect(currentCaseInput.mandatory).toBe(false)
            // FlowObject is indicated by attributes containing uiType=object
            expect(currentCaseInput.attributes).toContain('uiType=object')
            expect(currentCaseInput.attributes).toContain('uiTypeLabel=Object')
            // FlowObject nested fields are stored in sys_complex_object table
            // Verify max_length is large for object data
            expect(currentCaseInput.max_length).toBe(65000)
        }

        // Validate subflow outputs
        if (mergedRecords['sys_hub_flow_output']) {
            const outputs = mergedRecords['sys_hub_flow_output'].filter((o: any) => o.model === subflow.sys_id)
            expect(outputs.length).toBe(1) // Exact count: status

            const statusOutput = outputs.find((o: any) => o.element === 'status')
            expect(statusOutput).toBeDefined()
            expect(statusOutput.label).toBe('Status')
            expect(statusOutput.internal_type).toBe('string')
            expect(statusOutput.mandatory).toBe(true)
        }

        // Validate flow variables
        if (mergedRecords['sys_hub_flow_variable']) {
            const flowVars = mergedRecords['sys_hub_flow_variable'].filter((v: any) => v.model === subflow.sys_id)
            expect(flowVars.length).toBe(1) // Exact count: resolutionNotes

            const resolutionNotesVar = flowVars.find((v: any) => v.element === 'resolutionNotes')
            expect(resolutionNotesVar).toBeDefined()
            expect(resolutionNotesVar.label).toBe('Resolution notes')
            expect(resolutionNotesVar.internal_type).toBe('string')
            expect(resolutionNotesVar.mandatory).toBe(false)
            // Validate max_length for string flow variable
            expect(resolutionNotesVar.max_length).toBeDefined()
        }

        // Validate Flow Logic: assignSubflowOutputs
        if (mergedRecords['sys_hub_flow_logic_instance_v2']) {
            const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
            const assignOutputs = flowLogicInstances.find(
                (fl: any) => fl.flow === subflow.sys_id && fl.comment?.includes('Test Subflow Outputs 2')
            )
            expect(assignOutputs).toBeDefined()
            expect(assignOutputs.logic_definition).toBeDefined()

            // Decompress and validate assignSubflowOutputs values
            const assignOutputsValues = unzipInputArray(assignOutputs.values) as any
            const assignOutputsVar = (name: string) =>
                assignOutputsValues.outputsToAssign.find((v: any) => v.name === name)?.value

            // Validate status output assignment
            expect(assignOutputsVar('status')).toBe('Success')
        }
    })
})
